float circlesSDF(vec2 p, CircleInfo[4] closest) {
    float d = 1e5;

    for (int i = 0; i < 4; i++) {
        d =  min(d, length(p - closest[i].center) - closest[i].radius);
    }

    return d;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;   
    bool left = uv.x < 0.5;
    uv.x = uv.x + (left ? 0.0 : -0.5); 
    uv = uv - 0.5;   
    float aspect = (iResolution.x / iResolution.y);
    uv.x *= aspect;
    uv += vec2(1.0, 0.5); 
    uv.x -= 0.05;


    uvec4 closestIndices = fetchClosestN(uv, iChannel0);



    CircleInfo circles[4];
    for(int i = 0; i < 4; i++) {
        circles[i] = getCircleInfo(int(closestIndices[i]));
    }



    vec3 voronoiCol = vec3(
        xorshiftFloat(closestIndices[0] * 12345u),
        xorshiftFloat(closestIndices[0] * 34567u),
        xorshiftFloat(closestIndices[0] * 56789u)
    );

    float edgeDist = 1e5;
    for(int i = 0; i < 4; i++) {
        for(int j = i + 1; j < 4; j++) {
            if(areCirclesConnected(circles[i], circles[j])) {
                edgeDist = min(edgeDist, sdSegment(uv, circles[i].center, circles[j].center));
            }
        }
    }

    vec3 col = left ?  vec3(texture(iChannel2, uv).xy * 0.5 + 0.5, 0.0) :  voronoiCol;

    float edgeWidth = 0.00075;
    col = mix(col, vec3(1.0), S(edgeDist - edgeWidth));

    float sdf = texture(iChannel2, uv).z;
    float cSDF = (iFrame == 0) ? 1e5 : circlesSDF(uv, circles);

    col = mix(col, vec3(0.33) * (fract(sdf*12.0) - 0.5), S(-sdf));
    col = mix(col, vec3(1.0), S(abs(cSDF) - edgeWidth));

    fragColor = vec4(col, 1.0);
}

