ivec2 to2d(uint flatId, ivec2 resolution) {
    return ivec2(flatId, 0) % resolution;
}

Entity decodeEntity(sampler2D sampler, ivec2 id) {
    vec2 res = vec2(textureSize(sampler, 0));
    vec4 raw = texelFetch(sampler, id, 0);
    Entity entity;
    entity.position = raw.rg * res;
    return entity;
}

Entity decodeEntity(sampler2D sampler, uint flatId) {
    return decodeEntity(sampler, to2d(flatId, textureSize(sampler, 0)));
}



uint murmur3( in uint u )
{
  u ^= ( u >> 16 ); u *= 0x85EBCA6Bu;
  u ^= ( u >> 13 ); u *= 0xC2B2AE35u;
  u ^= ( u >> 16 );

  return u;
}

uint rngSeed = 314159265u;

uint xorshift(in uint value) {
    value ^= value << 13;
    value ^= value >> 17;
    value ^= value << 5;
    return value;
}

uint nextUint() {
    rngSeed = xorshift(rngSeed);
    return rngSeed;
}

float nextFloat() {
    return float(nextUint()) / float(uint(-1));
}


#define pi 3.14159265359
#define pi2 2.0 * pi

uint hash(inout uint x) {
    x ^= x >> 16;
    x *= 0x7feb352dU;
    x ^= x >> 15;
    x *= 0x846ca68bU;
    x ^= x >> 16;

    return x;
}

float randomFloat(inout uint state) {
    return float(hash(state)) / 4294967296.0;
} 

vec2 randomDir(inout uint state) {
    float z = randomFloat(state) * 2.0 - 1.0;
    float a = randomFloat(state) * pi2;
    float r = sqrt(1.0f - z * z);
    float x = r * cos(a);
    float y = r * sin(a);
    return vec2(x, y);
}

void sortClosest(
        inout vec4 distances,
        inout uvec4 indices, 
        uint index,
        vec2 center
        ) {
    if (index == uint(-1) || any(equal(indices, uvec4(index)))) {
        return;
    } 

    Entity e = decodeEntity(iChannel0, index);
    float dist = length(center - e.position);

    if (dist < distances[0]) {
        distances = vec4(dist, distances.xyz);
        indices = uvec4(index, indices.xyz);
    } else if (dist < distances[1]) {
        distances = vec4(distances.x, dist, distances.yz); 
        indices = uvec4(indices.x, index, indices.yz);
    } else if (dist < distances[2]) {
        distances = vec4(distances.xy, dist, distances.z); 
        indices = uvec4(indices.xy, index, indices.z);
    } else if (dist < distances[3]) {
        distances = vec4(distances.xyz, dist);             
        indices = uvec4(indices.xyz, index);
    }
}

void fetchAndSortClosest( inout vec4 distances, inout uvec4 idList, in vec2 samplePoint, in vec2 cellCenter ) {
    uvec4 ids = fetchClosest(samplePoint, iChannel1);

    for (int i = 0; i < 4; i++) {
        sortClosest(distances, idList, ids[i], cellCenter);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    uvec4 closestIndices = uvec4(-1);
    vec4 bestDistances = vec4(FLOAT_INF);

    uint seed = uint(iFrame) + uint(fragCoord.x) + uint(fragCoord.y);
    float rad = 4.0;

    fetchAndSortClosest(bestDistances, closestIndices, fragCoord, fragCoord);
    fetchAndSortClosest(bestDistances, closestIndices, fragCoord + randomDir(seed) * rad, fragCoord);
    fetchAndSortClosest(bestDistances, closestIndices, fragCoord + randomDir(seed) * rad, fragCoord);
    fetchAndSortClosest(bestDistances, closestIndices, fragCoord + randomDir(seed) * rad, fragCoord);
    fetchAndSortClosest(bestDistances, closestIndices, fragCoord + randomDir(seed) * rad, fragCoord);

    rngSeed = murmur3(uint(fragCoord.x)) ^ murmur3(floatBitsToUint(fragCoord.y)) ^ murmur3(floatBitsToUint(iTime));

    for (int i = 0; i < 16; i++) {
        sortClosest(bestDistances, closestIndices, wrap1d(nextUint()), fragCoord);
    }

    fragColor = uintBitsToFloat(closestIndices);
}

vec2 safeNormalize(vec2 v) {
    float epsilon = 1e-6;
    float len = length(v);
    if(len > epsilon) {
        return v / len;
    } else {
        return vec2(0.0, 0.0);
    }
}

float takenSpaceSDF(vec2 p, int currentIndex) {
    float shapeSDF = 1e5;

    for(int i = 0; i < currentIndex; i++) {
        vec4 circle = texelFetch(iChannel0, ivec2(i, 0), 0);
        if(circle.z <= 0.0) continue;

        float currentCircleSDF = length(p - circle.xy) - circle.z * 2.0;

        shapeSDF = smin(shapeSDF, currentCircleSDF, circle.z * 0.5);
    }

    return shapeSDF;
}



float availableSpaceSDF(vec2 p, int currentIndex) {
    float shapeSDF = texture(iChannel1, p).z;
    float takenSDF = takenSpaceSDF(p, currentIndex);


    return max(shapeSDF, -takenSDF);
}


vec3 snapToMedialAxis(vec2 candidate, int currentIndex) {
    vec2 pos = candidate;
    vec2 s = 4.0 * invRes;
    float snapped = 0.0;
    for(int iter = 0; iter < 64; iter++) {
        vec2 g = texture(iChannel1, pos).xy;
        float mg = length(g);
        // if(mg < 0.5) break;

        vec2 dir = g / mg;
        vec2 newPos = pos - s * dir;

        float newSpaceSDF = availableSpaceSDF(newPos, currentIndex);
        float oldSpaceSDF = availableSpaceSDF(pos, currentIndex);

        if (newSpaceSDF > 0.0) { snapped = 0.0; break; }
        if (newSpaceSDF > oldSpaceSDF) {
            s *= 0.8;

            if(s.x < 1e-5) { break; }
            continue;
        }

        pos = newPos;
    }

    return vec3(pos, snapped);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame == 0) { return; }

    if(fragCoord.y >= 1.0) {
        fragColor = vec4(0.0);
        return;
    }

    int circleIndex = int(fragCoord.x);

    if(circleIndex >= MAX_CIRCLES) {
        fragColor = vec4(0.5);
        return;
    }

    vec4 oldData = texelFetch(iChannel0, ivec2(circleIndex, 0), 0);
    vec2 center = oldData.xy;

    if(circleIndex > MAX_CIRCLES) {
        fragColor = oldData;
        return;
    }

    int currentCount = iFrame;

    srand(ivec2(fragCoord), iFrame);
    if(circleIndex == currentCount && currentCount < MAX_CIRCLES) {
        float bestScore = 0.0;
        vec2 bestPos = vec2(0.5);

        for(int c = 0; c < 64; c++) {
            vec3 randomCircle = texelFetch(iChannel0, ivec2(float(max(currentCount - 1, 0)) * frand(), 0), 0).xyz;
            vec2 candidate =  texelFetch(iChannel0, ivec2(float(max(currentCount - 1, 0)) * frand(), 0), 0).xy;
            candidate = currentCount == 0 ? vec2(0.5) : candidate;
            candidate += randomInCircle() * randomCircle.z + randomInCircle() * frand() * 0.5;
            candidate = min(max(vec2(0.0), candidate), 1.0);

            float sdfVal = texture(iChannel1, candidate).z;
            vec2 grad = texture(iChannel1, candidate).xy;

            if (sdfVal > 0.0) {
                candidate -= safeNormalize(grad) * sdfVal;
            }


            vec3 snappedResult = snapToMedialAxis(candidate, circleIndex);

            vec2 snapped = snappedResult.xy;
            float snappedTakenSpaceSDF = takenSpaceSDF(snapped, circleIndex);
            float snappedSpaceSDF = max(-snappedTakenSpaceSDF,  texture(iChannel1, snapped).z);
            vec2 snappedGrad = texture(iChannel1, snapped).xy;

            float snappedScore = -snappedSpaceSDF;

            float gradDot = dot(safeNormalize(texture(iChannel1, snapped).xy), safeNormalize(grad));


            if (
            snappedSpaceSDF < -RADIUS && 
            snappedScore > bestScore && 
            gradDot < 0.9
            ) {  
                MedialAxis medial = findMedialAxisDirections(snapped, RADIUS, iChannel1);
                if (medial.count != 0) {
                    bestScore = snappedScore;
                    bestPos = snapped;

                    center = bestPos;
                }
            }
        }
    }


    fragColor = vec4(center, RADIUS, 0.0);
}

float gtSDF(vec2 p) {
    p  = (p - 0.5) * 1.75;

    vec2 vertices[N];
    generateDeformedPolygon(vertices);
    float dist = sdPolygon(vertices, p);

    return dist / 1.75;
}


vec2 gtSDG(vec2 pos, vec2 eps) {
    vec2 n;

    float sdfRight  = gtSDF(vec2(pos.x + eps.x, pos.y));
    float sdfLeft   = gtSDF(vec2(pos.x - eps.x, pos.y));
    float sdfTop    = gtSDF(vec2(pos.x, pos.y + eps.y));
    float sdfBottom = gtSDF(vec2(pos.x, pos.y - eps.y));

    n.x = (sdfRight - sdfLeft) / (2.0 * eps.x);
    n.y = (sdfTop - sdfBottom) / (2.0 * eps.y);


    return n;
}

