#define N 36
float sdPolygon( in vec2[N] vn, in vec2 p )
{
    p /= 1.5;
    p.x = abs(p.x) + 0.15;
    float d = dot(p-v[0],p-v[0]);
    float s = 1.0;
    for( int i=0, j=N-1; i<N; j=i, i++ )
    {
        vec2 e = v[j] - v[i];
        vec2 w =    p - v[i];
        vec2 b = w - e*clamp( dot(w,e)/dot(e,e), 0.0, 1.0 );
        d = min( d, dot(b,b) );
        bvec3 c = bvec3(p.y>=v[i].y,p.y<v[j].y,e.x*w.y>e.y*w.x);
        if( all(c) || all(not(c)) ) s*=-1.0;  
    } 
    return (s*sqrt(d)) * 1.5 + 0.01;
}

float sdCircle(vec2 p, float r) {
    return length(p) - r;
}

float sdCapsule(vec2 p, vec2 a, vec2 b, float r) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

float sdHexagram(in vec2 p, in float r)
{
    const vec4 k = vec4(-0.5, 0.8660254038, 0.5773502692, 1.7320508076);
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= 2.0 * min(dot(k.yx, p), 0.0) * k.yx;
    p -= vec2(clamp(p.x, r * k.z, r * k.w), r);
    return length(p) * sign(p.y);
}



float noise(float x) {
    return fract(sin(x * 12.9898) * 43758.5453);
}


void generateDeformedPolygon(inout vec2 v[N]) {

    float baseRadius = 0.4;
    float noiseAmplitude = 0.15;
    float sineAmplitude = 0.2;
    float sineFrequency = 3.0;

    for(int i = 0; i < N; i++) {
        float angle = 2.0 * PI * float(i) / float(N);
        float currentNoise = noise(angle * float(i) * 8.0) *  noise(angle * float(i) * 2.0) * pow(1.0 - (float(i) / float(N)), 3.0) * 4.0 * noiseAmplitude;
        float currentSine = sin(angle * sineFrequency) * sineAmplitude * 0.5;
        float radius = baseRadius + currentNoise + currentSine;
        v[i] = vec2(radius * cos(angle), radius * sin(angle));
    }
}



vec2 sminN( float a, float b, float k ) {
    const float n = 3.; //3.
    float h = max( k-abs(a-b), 0.0 )/k;
    float m = pow(h, n)*0.5;
    float s = m*k/n; 
    return (a<b) ? vec2(a-s,m) : vec2(b-s,1.0-m);
}


float sdSegment(  vec2 p,  vec2 a,  vec2 b ) {
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );

    return length( pa - ba*h );
}

MedialAxis findMedialAxisDirections(vec2 c, float r, sampler2D gradientTex) {
    MedialAxis result;
    result.count = 0;

    const int SAMPLES = 4;
    const float ANGLE_STEP = 2.0 * PI / float(SAMPLES);
    vec2 samples[SAMPLES];
    vec2 gradients[SAMPLES];

    for(int i = 0; i < SAMPLES; i++) {
        float angle = float(i) * ANGLE_STEP;
        vec2 offset = vec2(cos(angle), sin(angle)) * (r * 0.5);
        samples[i] = c + offset;
        gradients[i] = normalize(texture(gradientTex, samples[i], 0.0).xy);
    }

    const float GRADIENT_THRESHOLD = 0.7;
    for(int i = 0; i < SAMPLES; i++) {
        int next = (i + 1) % SAMPLES;
        float dot_product = dot(gradients[i], gradients[next]);

        if(dot_product < GRADIENT_THRESHOLD && result.count < 5) {
            vec2 direction = normalize(vec2(
                gradients[i].y - gradients[next].y,
                gradients[next].x - gradients[i].x
            ));

            result.directions[result.count] = -direction;
            result.count++;
        }
    }

    return result;
}


uint wrap1d(uint flatId) {
    return flatId % uint(MAX_CIRCLES);
}

vec2 wrap2d(vec2 id, vec2 res) {
    return fract(id / res) * res;
}

uvec4 fetchClosestN(vec2 position, sampler2D voroBuffer) {
    vec2 res = vec2(textureSize(voroBuffer, 0));
    return floatBitsToUint(texelFetch(voroBuffer, ivec2(floor(position  * res)), 0));
}

uvec4 fetchClosest(vec2 position, sampler2D voroBuffer) {
    vec2 res = vec2(textureSize(voroBuffer, 0));
    return floatBitsToUint(texelFetch(voroBuffer, ivec2(wrap2d(position , res)), 0));
}
